"Schnelle Lieferung": "Hızlı teslimat",
"27+ Filialen": "27+ şube",
"<strong>27+</strong><span>Standorte</span>": "<strong>27+</strong><span>Şube</span>",
"<strong>18+</strong><span>Jahre Erfahrung</span>": "<strong>18+</strong><span>Yıllık deneyim</span>",
"<strong>1M+</strong><span>Zufriedene Kunden</span>": "<strong>1M+</strong><span>Mutlu müşteri</span>",
